import{_ as e,c as a,o as i,a0 as o}from"./chunks/framework.DKRgXLPU.js";const r=JSON.parse('{"title":"Introducción al juego mental - Guía del participante","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/es/participant-guide.md","filePath":"public/downloads/es/participant-guide.md"}');const n=e({name:"public/downloads/es/participant-guide.md"},[["render",function(e,r,n,t,l,s){return i(),a("div",null,[...r[0]||(r[0]=[o('<h1 id="introduccion-al-juego-mental-guia-del-participante" tabindex="-1">Introducción al juego mental - Guía del participante <a class="header-anchor" href="#introduccion-al-juego-mental-guia-del-participante" aria-label="Permalink to &quot;Introducción al juego mental - Guía del participante&quot;">​</a></h1><p><strong>Academia de petanca</strong><em>Desarrollo de jugadores de élite</em></p><hr><h2 id="bienvenido" tabindex="-1">Bienvenido <a class="header-anchor" href="#bienvenido" aria-label="Permalink to &quot;Bienvenido&quot;">​</a></h2><p>Hoy aprenderás técnicas prácticas de juego mental para mejorar tu rendimiento en la petanca.</p><h3 id="lo-que-aprenderas" tabindex="-1">Lo que aprenderás <a class="header-anchor" href="#lo-que-aprenderas" aria-label="Permalink to &quot;Lo que aprenderás&quot;">​</a></h3><ul><li>Por qué el entrenamiento mental es importante para los jugadores de élite</li><li>La diferencia entre el &quot;modo técnico&quot; y el &quot;modo de flujo&quot;</li><li>Cómo reconocer y gestionar a tu crítico interno</li><li>Técnicas sencillas para el manejo de la presión</li><li>Una rutina básica previa al disparo</li></ul><hr><h2 id="la-zona-estado-de-flujo" tabindex="-1">La zona/estado de flujo <a class="header-anchor" href="#la-zona-estado-de-flujo" aria-label="Permalink to &quot;La zona/estado de flujo&quot;">​</a></h2><h3 id="¿que-es-flow" tabindex="-1">¿Qué es Flow? <a class="header-anchor" href="#¿que-es-flow" aria-label="Permalink to &quot;¿Qué es Flow?&quot;">​</a></h3><p>El flujo es ese estado mágico donde:</p><ul><li>Todo parece fácil</li><li>El tiempo parece ralentizarse</li><li>No estás pensando, solo jugando.</li><li>Tu técnica se ejecuta perfectamente.</li></ul><h3 id="dos-modos-de-la-mente" tabindex="-1">Dos modos de la mente <a class="header-anchor" href="#dos-modos-de-la-mente" aria-label="Permalink to &quot;Dos modos de la mente&quot;">​</a></h3><p><strong>Modo de planificación (analítico)</strong></p><ul><li>Analizando el terreno</li><li>Elegir tu estrategia</li><li>Decidir el tiro</li><li>Evaluación de riesgos</li></ul><p><strong>Modo de ejecución (Flujo)</strong></p><ul><li>Confiando en tu cuerpo</li><li>No pensar en la técnica</li><li>Enfoque en el momento presente</li><li>Ejecución automática</li></ul><h3 id="el-interruptor" tabindex="-1">El interruptor <a class="header-anchor" href="#el-interruptor" aria-label="Permalink to &quot;El interruptor&quot;">​</a></h3><p>La habilidad clave: <strong>pasar del modo planificación al modo ejecución</strong></p><p><strong>Antes del disparo:</strong> Analizar, planificar, decidir <strong>Durante el disparo:</strong> Confía, fluye, ejecuta</p><hr><h2 id="el-critico-interno-vs-el-entrenador-interno" tabindex="-1">El crítico interno vs. el entrenador interno <a class="header-anchor" href="#el-critico-interno-vs-el-entrenador-interno" aria-label="Permalink to &quot;El crítico interno vs. el entrenador interno&quot;">​</a></h2><h3 id="tu-critico-interior-dice" tabindex="-1">Tu crítico interior dice: <a class="header-anchor" href="#tu-critico-interior-dice" aria-label="Permalink to &quot;Tu crítico interior dice:&quot;">​</a></h3><ul><li>&quot;¡Eso fue terrible!&quot;</li><li>&quot;Siempre cometes errores bajo presión&quot;</li><li>&quot;Todo el mundo te está viendo fracasar&quot;</li><li>&quot;No eres lo suficientemente bueno&quot;</li></ul><h3 id="tu-entrenador-interior-dice" tabindex="-1">Tu entrenador interior dice: <a class="header-anchor" href="#tu-entrenador-interior-dice" aria-label="Permalink to &quot;Tu entrenador interior dice:&quot;">​</a></h3><ul><li>¿Qué puedo aprender de esto?</li><li>&quot;Siguiente disparo, nuevo comienzo&quot;</li><li>&quot;Ya he hecho esta toma antes&quot;</li><li>&quot;Confía en el proceso&quot;</li></ul><h3 id="ejercicio-de-reencuadre" tabindex="-1">Ejercicio de reencuadre <a class="header-anchor" href="#ejercicio-de-reencuadre" aria-label="Permalink to &quot;Ejercicio de reencuadre&quot;">​</a></h3><p>Cuando notes a tu crítico interno:</p><ol><li><strong>Pausa</strong> - Reconocer el pensamiento crítico</li><li><strong>Reencuadre</strong>: ¿Qué diría tu entrenador?</li><li><strong>Reinicio</strong> - Toma 3 respiraciones</li><li><strong>Reenfocar</strong> - Siguiente toma</li></ol><hr><h2 id="herramientas-practicas" tabindex="-1">Herramientas prácticas <a class="header-anchor" href="#herramientas-practicas" aria-label="Permalink to &quot;Herramientas prácticas&quot;">​</a></h2><h3 id="reinicio-de-3-respiraciones" tabindex="-1">Reinicio de 3 respiraciones <a class="header-anchor" href="#reinicio-de-3-respiraciones" aria-label="Permalink to &quot;Reinicio de 3 respiraciones&quot;">​</a></h3><p>Utilice esto después de cometer errores o cuando se sienta presionado:</p><ol><li><strong>Respiración 1:</strong> Nota la tensión (¿dónde la sientes?)</li><li><strong>Respiración 2:</strong> Libera la tensión (déjala ir)</li><li><strong>Respiración 3:</strong> Vuelve a concentrarte en el ahora (esta toma, este momento)</li></ol><h3 id="rutina-previa-al-disparo" tabindex="-1">Rutina previa al disparo <a class="header-anchor" href="#rutina-previa-al-disparo" aria-label="Permalink to &quot;Rutina previa al disparo&quot;">​</a></h3><p>Crea consistencia con una rutina sencilla:</p><ol><li><strong>Visualiza</strong> - Visualiza la toma en tu mente</li><li><strong>Respira</strong> - Una respiración profunda</li><li><strong>Ancla</strong> - Toca tu bola, siente el peso</li><li><strong>Ejecutar</strong> - Confiar y lanzar</li></ol><h3 id="protocolo-de-recuperacion-de-errores" tabindex="-1">Protocolo de recuperación de errores <a class="header-anchor" href="#protocolo-de-recuperacion-de-errores" aria-label="Permalink to &quot;Protocolo de recuperación de errores&quot;">​</a></h3><p>Después de un mal tiro:</p><ol><li><strong>Reconocer</strong> - &quot;Eso no salió como estaba planeado&quot;</li><li><strong>Liberación</strong> - Reinicio físico (sacúdelo, camina)</li><li><strong>Reenfocar</strong> - &quot;El siguiente disparo es una nueva oportunidad&quot;</li><li><strong>Ejecutar</strong> - Confía en tu rutina</li></ol><hr><h2 id="su-plan-de-accion" tabindex="-1">Su plan de acción <a class="header-anchor" href="#su-plan-de-accion" aria-label="Permalink to &quot;Su plan de acción&quot;">​</a></h2><h3 id="esta-semana" tabindex="-1">Esta semana <a class="header-anchor" href="#esta-semana" aria-label="Permalink to &quot;Esta semana&quot;">​</a></h3><p>Elija UNA técnica para practicar:</p><ul><li>[ ] Reinicio de 3 respiraciones después de cada error</li><li>[ ] Rutina previa al lanzamiento en cada lanzamiento</li><li>[ ] Reformular un pensamiento del Crítico Interno por sesión</li><li>[ ] Practique el cambio del modo de planificación al modo de ejecución</li></ul><h3 id="sigue-tu-progreso" tabindex="-1">Sigue tu progreso <a class="header-anchor" href="#sigue-tu-progreso" aria-label="Permalink to &quot;Sigue tu progreso&quot;">​</a></h3><p>Aviso:</p><ul><li>¿Cuándo te sientes más en fluidez?</li><li>¿Qué es lo que desencadena tu crítico interno?</li><li>¿Qué técnica te ayuda más?</li><li>¿Cómo cambia tu rendimiento?</li></ul><hr><h2 id="recursos-y-proximos-pasos" tabindex="-1">Recursos y próximos pasos <a class="header-anchor" href="#recursos-y-proximos-pasos" aria-label="Permalink to &quot;Recursos y próximos pasos&quot;">​</a></h2><h3 id="continuar-aprendiendo" tabindex="-1">Continuar aprendiendo <a class="header-anchor" href="#continuar-aprendiendo" aria-label="Permalink to &quot;Continuar aprendiendo&quot;">​</a></h3><ul><li><strong>La Zona</strong> - Inmersión profunda en los estados de flujo</li><li><strong>Fuerza mental</strong> - Gestión avanzada de la presión</li><li><strong>Plantilla de objetivos</strong> - Estructura tu desarrollo</li><li><strong>Plantilla de diario</strong>: sigue tu progreso</li></ul><h3 id="practica-diariamente" tabindex="-1">Practica diariamente <a class="header-anchor" href="#practica-diariamente" aria-label="Permalink to &quot;Practica diariamente&quot;">​</a></h3><ul><li>5 minutos de respiración consciente</li><li>Visualiza tiros exitosos</li><li>Practica tu rutina previa al disparo</li><li>Replantear los pensamientos negativos</li></ul><hr><h2 id="conclusiones-clave" tabindex="-1">Conclusiones clave <a class="header-anchor" href="#conclusiones-clave" aria-label="Permalink to &quot;Conclusiones clave&quot;">​</a></h2><ol><li><strong>El estado de flujo es accesible</strong>: puedes aprender a ingresar a él de manera más consistente</li><li><strong>Tu voz interior importa</strong> - Entrénate, no critiques</li><li><strong>Las herramientas simples funcionan</strong>: 3 respiraciones, una rutina, un reinicio</li><li><strong>La práctica es clave</strong>: las habilidades mentales necesitan entrenamiento como las habilidades técnicas.</li></ol><hr><p><strong>Recuerda:</strong> El entrenamiento mental no se trata de pensar positivamente. Se trata de técnicas prácticas que te ayudan a alcanzar tu máximo rendimiento bajo presión.</p><hr><p><em>Visite carreau.app para obtener más recursos</em><em>Academia de Petanca - Desarrollo de jugadores de élite</em></p>',61)])])}]]);export{r as __pageData,n as default};
